import { Component, JSX, splitProps } from 'solid-js';

export interface BentoGridProps extends JSX.HTMLAttributes<HTMLDivElement> {
  cols?: number;
  gap?: number | string;
  rowHeight?: number | string;
}

export const BentoGrid: Component<BentoGridProps> = (props) => {
  const [local, others] = splitProps(props, ['cols', 'gap', 'rowHeight', 'class', 'children', 'style']);
  const cols = () => local.cols ?? 3;
  const gap = () => typeof local.gap === 'number' ? `${local.gap}px` : (local.gap ?? '20px');
  const autoRows = () => typeof local.rowHeight === 'number' ? `minmax(${local.rowHeight}px, auto)` : (local.rowHeight ?? 'minmax(180px, auto)');

  return (
    <div
      class={`exhuma-bento-grid grid w-full grid-flow-dense ${local.class || ''}`}
      style={{
        'grid-template-columns': `repeat(${cols()}, minmax(0, 1fr))`,
        gap: gap(),
        'grid-auto-rows': autoRows(),
        ...(typeof local.style === 'object' ? local.style : {}),
      }}
      {...others}
    >
      {local.children}
    </div>
  );
};

